package main

import (
	"fmt"
	"math"
)

const (
	N   = 105
	INF = 1000000000000000
)

type Matrix [N][N]int64

var (
	n   int
	T   int64
	a   [N]int
	d   Matrix
	dt  Matrix
	t   Matrix
	r   Matrix
)

func max(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func one(m *Matrix) {
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			m[i][j] = 0
		}
	}
}

func copyMat(dst, src *Matrix) {
	*dst = *src
}

func mul(a, b, c *Matrix) {
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			c[i][j] = -INF
			for k := 0; k < n; k++ {
				val := a[i][k] + b[k][j]
				if val > c[i][j] {
					c[i][j] = val
				}
			}
		}
	}
}

func binpow(a *Matrix, b int64, c *Matrix) {
	copyMat(a, &t)
	one(c)
	for b != 0 {
		if (b & 1) != 0 {
			mul(c, &t, &r)
			copyMat(&r, c)
		}
		mul(&t, &t, &r)
		copyMat(&r, &t)
		b >>= 1
	}
}

func main() {
	fmt.Scan(&n, &T)
	for i := 0; i < n; i++ {
		fmt.Scan(&a[i])
	}

	for s := 0; s < n; s++ {
		for i := 0; i < n; i++ {
			if a[i] < a[s] {
				d[s][i] = -INF
			} else {
				d[s][i] = 1
				for j := 0; j < i; j++ {
					if a[j] <= a[i] {
						d[s][i] = max(d[s][i], d[s][j]+1)
					}
				}
			}
		}
	}

	binpow(&d, T, &dt)

	var res int64 = 0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if dt[i][j] > res {
				res = dt[i][j]
			}
		}
	}
	fmt.Println(res)
}

